package com.example.starter.config;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 水泥窑掺烧业务合成参数。比例为小数（0.40 表示 40%），质量 kg，浓度 mg/Nm3。
 */
@ConfigurationProperties(prefix = "cement")
public class CementProperties {

    /** 替代燃料热量替代率上限，恰等于合法。 */
    private BigDecimal maxSubstitutionRate = new BigDecimal("0.40");
    /** 降掺保底比例，强制降掺的目标比例。 */
    private BigDecimal floorSubstitutionRate = new BigDecimal("0.10");
    /** 入窑氯总量限值 kg（高氯硫燃料质量加权），恰等于合法。 */
    private BigDecimal chlorineLimitKg = new BigDecimal("800.0");
    /** 入窑硫总量限值 kg，恰等于合法。 */
    private BigDecimal sulfurLimitKg = new BigDecimal("15000.0");
    /** 降掺指令下发后确认时限（分钟），恰满未确认即升级。 */
    private long commandConfirmTimeoutMinutes = 30;
    /** 连续小时均值超标触发当日禁烧的次数，恰等于触发。 */
    private int consecutiveExceedBan = 3;
    /** 各污染物小时均值排放限值 mg/Nm3，恰等于判达标。 */
    private Map<String, BigDecimal> emissionLimits = new LinkedHashMap<>();

    public BigDecimal getMaxSubstitutionRate() {
        return maxSubstitutionRate;
    }

    public void setMaxSubstitutionRate(BigDecimal maxSubstitutionRate) {
        this.maxSubstitutionRate = maxSubstitutionRate;
    }

    public BigDecimal getFloorSubstitutionRate() {
        return floorSubstitutionRate;
    }

    public void setFloorSubstitutionRate(BigDecimal floorSubstitutionRate) {
        this.floorSubstitutionRate = floorSubstitutionRate;
    }

    public BigDecimal getChlorineLimitKg() {
        return chlorineLimitKg;
    }

    public void setChlorineLimitKg(BigDecimal chlorineLimitKg) {
        this.chlorineLimitKg = chlorineLimitKg;
    }

    public BigDecimal getSulfurLimitKg() {
        return sulfurLimitKg;
    }

    public void setSulfurLimitKg(BigDecimal sulfurLimitKg) {
        this.sulfurLimitKg = sulfurLimitKg;
    }

    public long getCommandConfirmTimeoutMinutes() {
        return commandConfirmTimeoutMinutes;
    }

    public void setCommandConfirmTimeoutMinutes(long commandConfirmTimeoutMinutes) {
        this.commandConfirmTimeoutMinutes = commandConfirmTimeoutMinutes;
    }

    public int getConsecutiveExceedBan() {
        return consecutiveExceedBan;
    }

    public void setConsecutiveExceedBan(int consecutiveExceedBan) {
        this.consecutiveExceedBan = consecutiveExceedBan;
    }

    public Map<String, BigDecimal> getEmissionLimits() {
        return emissionLimits;
    }

    public void setEmissionLimits(Map<String, BigDecimal> emissionLimits) {
        this.emissionLimits = emissionLimits;
    }
}

package com.example.starter.config;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;

/**
 * 可控制时钟：生产环境使用 Asia/Shanghai 系统时钟；测试中可 {@link #travelTo(Instant)} 定点推进。
 */
public class ApplicationClock extends Clock {

    /** 业务时间统一按上海时区解释与落库。 */
    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");

    private volatile Clock delegate = Clock.system(ZONE);

    @Override
    public ZoneId getZone() {
        return delegate.getZone();
    }

    @Override
    public Clock withZone(ZoneId zone) {
        return delegate.withZone(zone);
    }

    @Override
    public Instant instant() {
        return delegate.instant();
    }

    /** 将时钟固定到指定时刻（测试用）。 */
    public void travelTo(Instant instant) {
        this.delegate = Clock.fixed(instant, ZONE);
    }

    /** 在当前时钟基础上推进固定分钟数（测试用）。 */
    public void advanceMinutes(long minutes) {
        this.delegate = Clock.fixed(instant().plusSeconds(minutes * 60L), ZONE);
    }

    /** 恢复为真实系统时钟（测试用）。 */
    public void reset() {
        this.delegate = Clock.system(ZONE);
    }

    /** 仅供避免未使用导入告警的工具引用。 */
    static ZoneOffset unusedOffset() {
        return ZoneOffset.UTC;
    }
}

package com.example.starter.config;

import java.time.Clock;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.scheduling.annotation.EnableScheduling;

/**
 * 业务 Bean 配置：可控时钟、参数绑定与定时任务开关。
 */
@Configuration
@EnableScheduling
@EnableConfigurationProperties(CementProperties.class)
public class AppConfig {

    @Bean
    public ApplicationClock applicationClock() {
        return new ApplicationClock();
    }

    @Bean
    public Clock clock(ApplicationClock applicationClock) {
        return applicationClock;
    }
}

package com.example.starter.domain;

/**
 * 方案状态：SUBMITTED→APPROVED/REJECTED→EXECUTING→STOPPED/BANNED→SEALED。
 */
public enum PlanStatus {
    /** 已申报，待审核。 */
    SUBMITTED,
    /** 审核通过，可启动执行。 */
    APPROVED,
    /** 整单拒绝（替代率超限、氯硫加权超限、许可过期等）。 */
    REJECTED,
    /** 执行中，占用窑。 */
    EXECUTING,
    /** 已停用（手动停止或切换时旧方案落态）。 */
    STOPPED,
    /** 连续3小时超标导致当日禁烧。 */
    BANNED,
    /** 日结封存，终态。 */
    SEALED
}

package com.example.starter.domain;

/**
 * 降掺指令链状态：触发→下发→执行确认，超时未确认自动升级。
 */
public enum CommandStatus {
    /** 小时均值超标已触发，尚未下发。 */
    TRIGGERED,
    /** 已下发，等待执行确认。 */
    ISSUED,
    /** 已执行确认，降掺到位。 */
    CONFIRMED,
    /** 下发恰满30分钟未确认，自动升级并强制降至保底比例。 */
    ESCALATED
}

package com.example.starter.domain;

/**
 * 方案整单拒绝/业务异常分类码。
 */
public enum RejectCategory {
    /** 替代燃料热量替代率超过上限（恰40%合法）。 */
    RATE_EXCEEDED,
    /** 高氯硫燃料加权入窑氯总量超过限值。 */
    CHLORINE_EXCEEDED,
    /** 高氯硫燃料加权入窑硫总量超过限值。 */
    SULFUR_EXCEEDED,
    /** 未绑定危废经营许可或许可已过期。 */
    LICENSE_INVALID,
    /** 状态机不允许当前操作。 */
    ILLEGAL_STATE,
    /** 同一窑同时刻已有执行中方案。 */
    KILN_OCCUPIED,
    /** 当日已被连续3小时超标禁烧。 */
    KILN_BANNED,
    /** 同 requestId 指纹不一致。 */
    IDEMPOTENT_CONFLICT
}

package com.example.starter.domain;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态与拒绝分类，由全局异常处理统一转换。
 */
public class BusinessException extends RuntimeException {

    private final HttpStatus httpStatus;
    private final RejectCategory category;

    public BusinessException(HttpStatus httpStatus, RejectCategory category, String message) {
        super(message);
        this.httpStatus = httpStatus;
        this.category = category;
    }

    public static BusinessException conflict(RejectCategory category, String message) {
        return new BusinessException(HttpStatus.CONFLICT, category, message);
    }

    public static BusinessException notFound(String message) {
        return new BusinessException(HttpStatus.NOT_FOUND, RejectCategory.ILLEGAL_STATE, message);
    }

    public static BusinessException unprocessable(RejectCategory category, String message) {
        return new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY, category, message);
    }

    public HttpStatus getHttpStatus() {
        return httpStatus;
    }

    public RejectCategory getCategory() {
        return category;
    }
}

