/**
 * 排放读数访问：去重唯一约束 (plan_id, measure_point, sample_time)。
 */
@Repository
public class ReadingRepository {

    private static final RowMapper<EmissionReading> MAPPER = (ResultSet rs, int n) -> new EmissionReading(
            rs.getLong("id"),
            rs.getLong("plan_id"),
            rs.getString("kiln_id"),
