package com.example.starter.repo;

import java.sql.ResultSet;
import java.sql.Timestamp;
import java.time.LocalDateTime;
import java.util.List;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import com.example.starter.domain.HourlyAssessment;

/**
 * 小时评估结果访问，按 (plan_id, hour_start) 幂等 upsert。
 */
@Repository
public class HourlyAssessmentRepository {

    private static final RowMapper<HourlyAssessment> MAPPER = (ResultSet rs, int n) -> new HourlyAssessment(
            rs.getLong("id"),
            rs.getLong("plan_id"),
            rs.getObject("hour_start", LocalDateTime.class),
            rs.getBigDecimal("nox_avg"),
            rs.getBigDecimal("so2_avg"),
            rs.getBigDecimal("dust_avg"),
            rs.getInt("reading_count"),
            rs.getBoolean("exceeded"),
            rs.getString("pollutants"),
            rs.getInt("consecutive_no"));

    private final JdbcTemplate jdbc;

    public HourlyAssessmentRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 幂等写入小时评估（乱序读数归位后可重算覆盖）。
     */
    public void upsert(HourlyAssessment a) {
        int updated = jdbc.update("""
                UPDATE hourly_assessment
                SET nox_avg = ?, so2_avg = ?, dust_avg = ?, reading_count = ?,
                    exceeded = ?, pollutants = ?, consecutive_no = ?, updated_at = CURRENT_TIMESTAMP
                WHERE plan_id = ? AND hour_start = ?
                """,
                a.noxAvg(), a.so2Avg(), a.dustAvg(), a.readingCount(),
                a.exceeded(), a.pollutants(), a.consecutiveNo(),
                a.planId(), Timestamp.valueOf(a.hourStart()));
        if (updated == 0) {
            try {
                jdbc.update("""
                        INSERT INTO hourly_assessment
                            (plan_id, hour_start, nox_avg, so2_avg, dust_avg, reading_count,
                             exceeded, pollutants, consecutive_no)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        a.planId(), Timestamp.valueOf(a.hourStart()),
                        a.noxAvg(), a.so2Avg(), a.dustAvg(), a.readingCount(),
                        a.exceeded(), a.pollutants(), a.consecutiveNo());
            } catch (DuplicateKeyException concurrent) {
                // 并发重算：改用更新覆盖
                jdbc.update("""
                        UPDATE hourly_assessment
                        SET nox_avg = ?, so2_avg = ?, dust_avg = ?, reading_count = ?,
                            exceeded = ?, pollutants = ?, consecutive_no = ?, updated_at = CURRENT_TIMESTAMP
                        WHERE plan_id = ? AND hour_start = ?
                        """,
                        a.noxAvg(), a.so2Avg(), a.dustAvg(), a.readingCount(),
                        a.exceeded(), a.pollutants(), a.consecutiveNo(),
                        a.planId(), Timestamp.valueOf(a.hourStart()));
            }
        }
    }

    /** 取方案截至指定小时（含）、按小时排序的评估序列，用于连续超标计数。 */
    public List<HourlyAssessment> findByPlanUpTo(long planId, LocalDateTime hourStart) {
        return jdbc.query("""
                SELECT id, plan_id, hour_start, nox_avg, so2_avg, dust_avg, reading_count,
                       exceeded, pollutants, consecutive_no
                FROM hourly_assessment
                WHERE plan_id = ? AND hour_start <= ?
                ORDER BY hour_start
                """, MAPPER, planId, Timestamp.valueOf(hourStart));
    }

    public List<HourlyAssessment> findByPlanAndDate(long planId, java.time.LocalDate date) {
        return jdbc.query("""
                SELECT id, plan_id, hour_start, nox_avg, so2_avg, dust_avg, reading_count,
                       exceeded, pollutants, consecutive_no
                FROM hourly_assessment
                WHERE plan_id = ? AND hour_start >= ? AND hour_start < ?
                ORDER BY hour_start
                """, MAPPER, planId,
                Timestamp.valueOf(date.atStartOfDay()),
                Timestamp.valueOf(date.plusDays(1).atStartOfDay()));
    }
}

package com.example.starter.repo;

import java.math.BigDecimal;
import java.sql.Date;
import java.sql.Timestamp;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.List;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * 日结记录访问。超标时段与降掺记录以 JSON 字符串落库，封存为终态。
 */
@Repository
public class DailySummaryRepository {

    /**
     * 日结持久化视图。
     */
    public record DailySummaryRow(
            long planId,
            LocalDate summaryDate,
            BigDecimal actualSubstitutionRate,
            String exceededPeriodsJson,
            String reductionRecordsJson,
            String effectiveHoursJson,
            boolean sealed,
            LocalDateTime sealedAt) {
    }

    private final JdbcTemplate jdbc;

    public DailySummaryRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public DailySummaryRow find(long planId, LocalDate date) {
        List<DailySummaryRow> list = jdbc.query("""
                SELECT plan_id, summary_date, actual_substitution_rate, exceeded_periods,
                       reduction_records, effective_hours, sealed, sealed_at
                FROM daily_summary WHERE plan_id = ? AND summary_date = ?
                """, (rs, n) -> new DailySummaryRow(
                rs.getLong("plan_id"),
                rs.getObject("summary_date", LocalDate.class),
                rs.getBigDecimal("actual_substitution_rate"),
                rs.getString("exceeded_periods"),
                rs.getString("reduction_records"),
                rs.getString("effective_hours"),
                rs.getBoolean("sealed"),
                rs.getObject("sealed_at", LocalDateTime.class)), planId, Date.valueOf(date));
        return list.isEmpty() ? null : list.get(0);
    }

    /** 幂等 upsert 日结（未封存时可重算覆盖；封存后服务层拒绝覆盖）。 */
    public void upsert(DailySummaryRow row) {
        jdbc.update("""
                MERGE INTO daily_summary
                    (id, plan_id, summary_date, actual_substitution_rate, exceeded_periods,
                     reduction_records, effective_hours, sealed, created_at, sealed_at)
                KEY(plan_id, summary_date)
                VALUES (
                    (SELECT id FROM daily_summary WHERE plan_id = ? AND summary_date = ?),
                    ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?)
                """,
                row.planId(), Date.valueOf(row.summaryDate()),
                row.planId(), Date.valueOf(row.summaryDate()),
                row.actualSubstitutionRate(),
                row.exceededPeriodsJson(), row.reductionRecordsJson(), row.effectiveHoursJson(),
                row.sealed(),
                row.sealedAt() == null ? null : Timestamp.valueOf(row.sealedAt()));
    }

    public int markSealed(long planId, LocalDate date, LocalDateTime sealedAt) {
        return jdbc.update("""
                UPDATE daily_summary SET sealed = TRUE, sealed_at = ?
                WHERE plan_id = ? AND summary_date = ?
                """, Timestamp.valueOf(sealedAt), planId, Date.valueOf(date));
    }
}

