                List.of(TestFixtures.normalFuel())));
        PlanResultResponse p3 = service.submit(TestFixtures.submit("REQ-SWC-C", KILN,
                VALID_LICENSE, "0.1500", DAY.atTime(0, 0), DAY.atTime(23, 59),
                List.of(TestFixtures.normalFuel())));
