        service.switchPlan(new SwitchPlanRequest("REQ-SWC-1", KILN, p2.planNo()));
        BusinessException ex = assertThrows(BusinessException.class, () -> service.switchPlan(
                new SwitchPlanRequest("REQ-SWC-1", KILN, p3.planNo())));
